import json
import sys
def main(argv):
    try:
        with open(argv[0]) as stream:
            config = json.load(stream)
    except OSError as exc:
        print(f"error: cannot read config file {argv[0]!r}: {exc}", file=sys.stderr)
        return 2
    except json.JSONDecodeError as exc:
        print(f"error: invalid JSON in config file {argv[0]!r}: {exc}", file=sys.stderr)
        return 2
    if not isinstance(config, dict) or "name" not in config:
        print("error: config is missing required 'name' field", file=sys.stderr)
        return 2
    print(config["name"])
    return 0
if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
